import { AutoTokenizer, env } from "@huggingface/transformers";
import * as ort from "onnxruntime-web/webgpu";
import type {
  SmokeBackend,
  TokenBudgetResult,
  WebGPUSmokeResult,
  WebGPUSpikeRequest,
  WebGPUSpikeResponse,
} from "./protocol";

type OnnxEnvironment = typeof env.backends.onnx & {
  wasm?: {
    wasmPaths?: string;
  };
};

// ONNX Runtime's MIT-licensed mul_1.onnx test fixture, embedded to keep the
// smoke test deterministic and independent of model/CDN availability.
const ORT_SMOKE_MODEL_BASE64 =
  "CAMSBmNoZW50YTpwChUKAVgKAVcSAVkaBW11bF8xIgNNdWwSCG11bCB0ZXN0KiMIAwgCEAEiGAAAgD8AAABAAABAQAAAgEAAAKBAAADAQEIBV1oTCgFYEg4KDAgBEggKAggDCgIIAmITCgFZEg4KDAgBEggKAggDCgIIAkIECgAQBw==";

function post(response: WebGPUSpikeResponse): void {
  self.postMessage(response);
}

function decodeBase64(value: string): Uint8Array {
  return Uint8Array.from(atob(value), (character) => character.charCodeAt(0));
}

async function runOrtSmoke(
  ortWasmBaseUrl: string,
  backend: SmokeBackend,
): Promise<number[]> {
  ort.env.wasm.wasmPaths = ortWasmBaseUrl;
  ort.env.wasm.numThreads = 1;
  ort.env.wasm.proxy = false;

  const session = await ort.InferenceSession.create(
    decodeBase64(ORT_SMOKE_MODEL_BASE64),
    {
      executionProviders: [backend],
    },
  );
  try {
    const input = new ort.Tensor(
      "float32",
      Float32Array.from([1, 2, 3, 4, 5, 6]),
      [3, 2],
    );
    const outputs = await session.run({ X: input });
    const values = Array.from(outputs.Y.data as Float32Array);
    const expected = [1, 4, 9, 16, 25, 36];
    if (
      values.length !== expected.length ||
      values.some((value, index) => value !== expected[index])
    ) {
      throw new Error(`Unexpected ONNX Runtime ${backend} output: ${values}`);
    }
    return values;
  } finally {
    await session.release();
  }
}

/**
 * Acquire an adapter, retrying with `forceFallbackAdapter` so machines without
 * a usable discrete/integrated GPU can still exercise the real WebGPU code
 * path via a software adapter (for example Chrome's SwiftShader).
 */
async function requestAnyAdapter(): Promise<{
  adapter: GPUAdapter | null;
  usedFallbackAdapter: boolean;
}> {
  const preferred = await navigator.gpu.requestAdapter({
    powerPreference: "high-performance",
  });
  if (preferred) return { adapter: preferred, usedFallbackAdapter: false };

  const fallback = await navigator.gpu.requestAdapter({
    forceFallbackAdapter: true,
  });
  return { adapter: fallback, usedFallbackAdapter: fallback !== null };
}

async function runComputeSmoke(
  ortWasmBaseUrl: string,
  allowWasmFallback: boolean,
): Promise<WebGPUSmokeResult> {
  const startedAt = performance.now();
  const onnx = env.backends.onnx as OnnxEnvironment;
  onnx.wasm ??= {};
  onnx.wasm.wasmPaths = ortWasmBaseUrl;
  env.allowRemoteModels = false;
  env.allowLocalModels = true;

  const base = {
    transformersVersion: env.version,
    onnxRuntimeVersion: ort.env.versions.web ?? ort.env.versions.common,
  };

  const degrade = async (reason: string): Promise<WebGPUSmokeResult> => {
    if (!allowWasmFallback) throw new Error(reason);
    return {
      ...base,
      backend: "wasm",
      usedFallbackAdapter: false,
      webgpuUnavailableReason: reason,
      shaderF16: false,
      ortOutput: await runOrtSmoke(ortWasmBaseUrl, "wasm"),
      durationMs: Math.round(performance.now() - startedAt),
    };
  };

  if (!self.isSecureContext || !navigator.gpu) {
    return degrade(
      "WebGPU requires a secure context and navigator.gpu; navigator.gpu is unavailable.",
    );
  }

  const { adapter, usedFallbackAdapter } = await requestAnyAdapter();
  if (!adapter) {
    return degrade(
      "No WebGPU adapter is available (including forceFallbackAdapter).",
    );
  }

  const ortOutput = await runOrtSmoke(ortWasmBaseUrl, "webgpu");
  const device = await adapter.requestDevice();
  const output = device.createBuffer({
    size: 4,
    usage: GPUBufferUsage.STORAGE | GPUBufferUsage.COPY_SRC,
  });
  const readback = device.createBuffer({
    size: 4,
    usage: GPUBufferUsage.COPY_DST | GPUBufferUsage.MAP_READ,
  });

  try {
    const shader = device.createShaderModule({
      code: `
        @group(0) @binding(0) var<storage, read_write> output: array<u32>;
        @compute @workgroup_size(1)
        fn main() {
          output[0] = 42u;
        }
      `,
    });
    const pipeline = await device.createComputePipelineAsync({
      layout: "auto",
      compute: { module: shader, entryPoint: "main" },
    });
    const bindGroup = device.createBindGroup({
      layout: pipeline.getBindGroupLayout(0),
      entries: [{ binding: 0, resource: { buffer: output } }],
    });
    const encoder = device.createCommandEncoder();
    const pass = encoder.beginComputePass();
    pass.setPipeline(pipeline);
    pass.setBindGroup(0, bindGroup);
    pass.dispatchWorkgroups(1);
    pass.end();
    encoder.copyBufferToBuffer(output, 0, readback, 0, 4);
    device.queue.submit([encoder.finish()]);
    await device.queue.onSubmittedWorkDone();
    await readback.mapAsync(GPUMapMode.READ);
    const computeValue = new Uint32Array(readback.getMappedRange().slice(0))[0];
    readback.unmap();

    const info = adapter.info;
    return {
      ...base,
      backend: "webgpu",
      usedFallbackAdapter,
      adapter: {
        vendor: info.vendor || undefined,
        architecture: info.architecture || undefined,
        device: info.device || undefined,
        description: info.description || undefined,
      },
      shaderF16: adapter.features.has("shader-f16"),
      maxBufferSize: Number(adapter.limits.maxBufferSize),
      maxStorageBufferBindingSize: Number(
        adapter.limits.maxStorageBufferBindingSize,
      ),
      computeValue,
      ortOutput,
      durationMs: Math.round(performance.now() - startedAt),
    };
  } finally {
    output.destroy();
    readback.destroy();
    device.destroy();
  }
}

async function countTokenBudget(input: {
  modelId: string;
  revision: string;
  systemPrompt: string;
  tools: unknown[];
}): Promise<TokenBudgetResult> {
  const startedAt = performance.now();
  env.allowRemoteModels = true;
  env.allowLocalModels = false;

  const tokenizer = await AutoTokenizer.from_pretrained(input.modelId, {
    revision: input.revision,
  });
  const systemOnly = tokenizer.apply_chat_template(
    [{ role: "system", content: input.systemPrompt }],
    {
      tokenize: true,
      return_tensor: false,
      return_dict: false,
      add_generation_prompt: false,
    },
  );
  const noTools = tokenizer.apply_chat_template(
    [
      { role: "system", content: input.systemPrompt },
      { role: "user", content: "Feasibility token-budget probe." },
    ],
    {
      tokenize: true,
      return_tensor: false,
      return_dict: false,
      add_generation_prompt: true,
    },
  );
  const withTools = tokenizer.apply_chat_template(
    [
      { role: "system", content: input.systemPrompt },
      { role: "user", content: "Feasibility token-budget probe." },
    ],
    {
      tools: input.tools,
      tokenize: true,
      return_tensor: false,
      return_dict: false,
      add_generation_prompt: true,
    },
  );

  return {
    systemPromptTokens: systemOnly.length,
    toolSchemaTokens: Math.max(0, withTools.length - noTools.length),
    combinedPromptTokens: withTools.length,
    toolCount: input.tools.length,
    durationMs: Math.round(performance.now() - startedAt),
  };
}

self.onmessage = async (event: MessageEvent<WebGPUSpikeRequest>) => {
  const request = event.data;
  try {
    if (request.type === "smoke") {
      post({
        type: "smoke_complete",
        requestId: request.requestId,
        result: await runComputeSmoke(
          request.ortWasmBaseUrl,
          request.allowWasmFallback,
        ),
      });
      return;
    }

    post({
      type: "token_budget_complete",
      requestId: request.requestId,
      result: await countTokenBudget(request),
    });
  } catch (error) {
    post({
      type: "error",
      requestId: request.requestId,
      message: error instanceof Error ? error.message : String(error),
    });
  }
};
